{
  "source_id": "TEXT",
  "cast": [
    {
      "id": "P01",
      "name": "国王"
    },
    {
      "id": "P02",
      "name": "哈姆莱特"
    },
    {
      "id": "P03",
      "name": "雷欧提斯"
    },
    {
      "id": "P04",
      "name": "王后"
    },
    {
      "id": "P05",
      "name": "奥斯里克"
    }
  ],
  "locations": [
    {
      "id": "L01",
      "name": "王宫大厅"
    }
  ],
  "scenes": [
    {
      "sceneId": "L01",
      "characters": [
        "P01",
        "P02",
        "P03",
        "P04",
        "P05"
      ],
      "flow": [
        {
          "action": "国王举起酒杯，鼓声与喇叭响起。"
        },
        {
          "speaker": "P01",
          "line": "若哈姆莱特胜，便鸣炮，赐他一颗珍珠。",
          "mode": "spoken"
        },
        {
          "action": "哈姆莱特与雷欧提斯举剑比试。"
        },
        {
          "speaker": "P02",
          "line": "一剑。",
          "mode": "spoken"
        },
        {
          "speaker": "P03",
          "line": "没有击中。",
          "mode": "spoken"
        },
        {
          "speaker": "P05",
          "line": "中了，很明显。",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "且慢，拿酒来。这颗珍珠给你。",
          "mode": "spoken"
        },
        {
          "action": "喇叭齐奏，炮声响起。"
        },
        {
          "speaker": "P02",
          "line": "让我先赛完这一局，杯子放一旁。",
          "mode": "spoken"
        },
        {
          "speaker": "P04",
          "line": "来，拿我的手巾擦汗。我为你祝胜。",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "王后，不要喝。",
          "mode": "spoken"
        },
        {
          "speaker": "P04",
          "line": "我要喝的，陛下。",
          "mode": "spoken"
        },
        {
          "speaker": "P02",
          "line": "母亲，我现在还不敢喝。",
          "mode": "spoken"
        },
        {
          "action": "王后接过酒杯，一饮而尽。"
        },
        {
          "speaker": "P03",
          "line": "陛下，现在我一定要击中他了。",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "我怕你击不中他。",
          "mode": "spoken"
        },
        {
          "speaker": "P02",
          "line": "第三回合了，请使出全部本领。",
          "mode": "spoken"
        },
        {
          "action": "雷欧提斯挺剑，刺中哈姆莱特。"
        },
        {
          "action": "两人夺剑，彼此受伤。"
        },
        {
          "speaker": "P01",
          "line": "分开他们！他们动火了。",
          "mode": "spoken"
        },
        {
          "action": "王后倒地。"
        },
        {
          "speaker": "P04",
          "line": "不，那杯酒，我中毒了。",
          "mode": "spoken"
        },
        {
          "action": "王后死去。"
        },
        {
          "speaker": "P02",
          "line": "啊，阴谋！把门锁上！",
          "mode": "spoken"
        },
        {
          "action": "雷欧提斯倒地。"
        },
        {
          "speaker": "P03",
          "line": "凶手就是国王，我的剑上有毒。",
          "mode": "spoken"
        },
        {
          "speaker": "P03",
          "line": "你活不过半小时，我母亲也中毒了。",
          "mode": "spoken"
        },
        {
          "speaker": "P02",
          "line": "毒药，发挥你的力量吧！",
          "mode": "spoken"
        },
        {
          "action": "哈姆莱特刺向国王。"
        },
        {
          "speaker": "P01",
          "line": "啊，帮帮我，我不过受了点伤。",
          "mode": "spoken"
        },
        {
          "speaker": "P02",
          "line": "奸王，喝干这杯毒药，跟母亲去吧！",
          "mode": "spoken"
        },
        {
          "action": "国王死去。"
        },
        {
          "speaker": "P03",
          "line": "让我们互相宽恕，我不怪你。",
          "mode": "spoken"
        },
        {
          "action": "雷欧提斯死去。"
        }
      ]
    }
  ]
}

