        },
        {
          "speaker": "P01",
          "line": "王后，不要喝。",
          "mode": "spoken"
        },
        {
          "speaker": "P04",
          "line": "我要喝的，陛下。",
          "mode": "spoken"
        },
        {
          "speaker": "P02",
          "line": "母亲，我现在还不敢喝。",
          "mode": "spoken"
        },
        {
          "action": "王后接过酒杯，一饮而尽。"
        },
        {
          "speaker": "P03",
          "line": "陛下，现在我一定要击中他了。",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "我怕你击不中他。",
          "mode": "spoken"
        },
        {
          "speaker": "P02",
          "line": "第三回合了，请使出全部本领。",
          "mode": "spoken"
        },
        {
          "action": "雷欧提斯挺剑，刺中哈姆莱特。"
        },
        {
          "action": "两人夺剑，彼此受伤。"
        },
        {
          "speaker": "P01",
          "line": "分开他们！他们动火了。",
          "mode": "spoken"
        },
        {
          "action": "王后倒地。"
        },
        {
          "speaker": "P04",
          "line": "不，那杯酒，我中毒了。",
          "mode": "spoken"
        },
        {
          "action": "王后死去。"
        },
        {
          "speaker": "P02",
          "line": "啊，阴谋！把门锁上！",
          "mode": "spoken"
        },
        {
          "action": "雷欧提斯倒地。"
        },
        {
          "speaker": "P03",
          "line": "凶手就是国王，我的剑上有毒。",
          "mode": "spoken"
        },
        {
          "speaker": "P03",
          "line": "你活不过半小时，我母亲也中毒了。",
          "mode": "spoken"
        },
        {
          "speaker": "P02",
          "line": "毒药，发挥你的力量吧！",
          "mode": "spoken"
        },
        {
          "action": "哈姆莱特刺向国王。"
        },
        {
          "speaker": "P01",
          "line": "啊，帮帮我，我不过受了点伤。",
          "mode": "spoken"
        },
        {
          "speaker": "P02",
          "line": "奸王，喝干这杯毒药，跟母亲去吧！",
          "mode": "spoken"
        },
        {
          "action": "国王死去。"
        },
        {
          "speaker": "P03",
          "line": "让我们互相宽恕，我不怪你。",
          "mode": "spoken"
        },
        {
          "action": "雷欧提斯死去。"
        }
      ]
    }
