{
  "source_id": "TEXT",
  "cast": [
    {
      "id": "P01",
      "name": "哥舒"
    },
    {
      "id": "P02",
      "name": "帝子"
    },
    {
      "id": "P03",
      "name": "军师"
    },
    {
      "id": "P04",
      "name": "公卿"
    },
    {
      "id": "P05",
      "name": "二圣"
    }
  ],
  "locations": [
    {
      "id": "L01",
      "name": "函关"
    },
    {
      "id": "L02",
      "name": "两京"
    }
  ],
  "scenes": [
    {
      "sceneId": "L01",
      "characters": [
        "P01"
      ],
      "flow": [
        {
          "action": "哥舒按剑立于函关。"
        },
        {
          "speaker": "P01",
          "line": "炎凉几度改，九土横溃，山河失序。",
          "mode": "spoken"
        },
        {
          "action": "烟尘压城，草木摇动。"
        },
        {
          "speaker": "P01",
          "line": "汉甲连胡兵，沙尘暗云海，前路难辨。",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "草木摇杀气，星辰无光彩，天地失色。",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "白骨成丘山，苍生竟何罪，谁人作答？",
          "mode": "spoken"
        },
        {
          "action": "长戟列门，城门洞开。"
        },
        {
          "speaker": "P01",
          "line": "函关壮帝居，国命悬哥舒，一夫当关。",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "长戟三十万，开门纳凶渠，门开即溃。",
          "mode": "spoken"
        }
      ]
    },
    {
      "sceneId": "L02",
      "characters": [
        "P04",
        "P05",
        "P02",
        "P03"
      ],
      "flow": [
        {
          "action": "公卿列位，宫门空寂。"
        },
        {
          "speaker": "P04",
          "line": "公卿如犬羊，忠谡醢与葅，朝堂失声。",
          "mode": "spoken"
        },
        {
          "action": "二圣离宫，两京成墟。"
        },
        {
          "speaker": "P05",
          "line": "二圣出游豫，两京遂丘墟，宫阙无人。",
          "mode": "spoken"
        },
        {
          "speaker": "P02",
          "line": "帝子许专征，秉旄控强楚，旌旗待命。",
          "mode": "spoken"
        },
        {
          "speaker": "P03",
          "line": "节制非桓文，军师拥熊虎，号令不齐。",
          "mode": "spoken"
        },
        {
          "action": "军师持旄，旌旗列阵。"
        },
        {
          "speaker": "P03",
          "line": "熊虎在军，进退由人。",
          "mode": "spoken"
        },
        {
          "speaker": "P04",
          "line": "人心失去就，贼势腾风雨，风雨压城。",
          "mode": "spoken"
        },
        {
          "speaker": "P05",
          "line": "两京丘墟，宫门空锁，二圣何归？",
          "mode": "spoken"
        }
      ]
    }
  ]
}

