  "scenes": [
    {
      "sceneId": "L01",
      "characters": [
        "P01",
        "P02"
      ],
      "flow": [
        {
          "action": "宗定伯独自走在夜路上。"
        },
        {
          "speaker": "P02",
          "line": "我是鬼。",
          "mode": "spoken"
        },
        {
          "action": "鬼停在路边，看着定伯。"
        },
        {
          "speaker": "P02",
          "line": "你是谁？",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "我也是鬼。",
          "mode": "spoken"
        },
        {
          "action": "定伯稳住脚步，没有后退。"
        },
        {
          "speaker": "P02",
          "line": "想去哪儿？",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "去宛市。",
          "mode": "spoken"
        },
        {
          "speaker": "P02",
          "line": "我也去宛市。",
          "mode": "spoken"
        },
        {
          "action": "两人并排往前走。"
        },
        {
          "speaker": "P02",
          "line": "走得太急，轮流背吧。",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "好。",
          "mode": "spoken"
        },
        {
          "action": "鬼先背起定伯。"
        },
        {
          "action": "定伯趴在鬼背上走了几里。"
        },
        {
          "speaker": "P02",
          "line": "你怎么这么重？不是鬼？",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "我是新鬼，所以重。",
          "mode": "spoken"
        },
        {
          "action": "定伯翻身背起鬼。"
        },
        {
          "action": "定伯背着鬼，脚步不停。"
        },
        {
          "speaker": "P01",
          "line": "我是新鬼，怕什么？",
          "mode": "spoken"
        },
        {
          "speaker": "P02",
          "line": "只讨厌人唾沫。",
          "mode": "spoken"
        },
        {
          "action": "两人继续赶路。"
        }
      ]
    },
    {
      "sceneId": "L02",
      "characters": [
        "P01",
        "P02"
      ],
      "flow": [
        {
          "action": "路边出现一条浅溪。"
        },
        {
          "action": "定伯让鬼先渡水。"
        },
        {
          "action": "鬼落入水中，没有声音。"
        },
        {
          "action": "定伯侧耳听水。"
        },
        {
          "action": "定伯自己踏入溪中。"
        },
        {
          "action": "水声哗哗响起。"
        },
        {
          "speaker": "P02",
          "line": "怎么有声音？",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "新死，不习惯渡水，别怪我。",
          "mode": "spoken"
        },
        {
          "action": "两人过了溪。"
        }
      ]
    },
    {
      "sceneId": "L03",
      "characters": [
        "P01",
        "P02"
      ],
      "flow": [
        {
          "action": "宛市渐近，街市出现。"
        },
        {
          "action": "定伯突然把鬼扛到肩上。"
        },
        {
          "action": "定伯紧紧按住鬼。"
        },
        {
          "speaker": "P02",
          "line": "放我下来！",
          "mode": "spoken"
        },
        {
          "action": "鬼挣扎着要落下。"
        },
        {
          "action": "定伯径直走进市场。"
        },
        {
          "action": "定伯把鬼放下地上。"
        },
        {
          "action": "鬼落地，变成一只羊。"
        },
        {
          "action": "定伯朝羊唾一口。"
        },
        {
          "action": "定伯把羊牵到摊前。"
        },
        {
          "action": "定伯收下卖羊的钱。"
        },
        {
          "speaker": "P01",
          "line": "卖得一千五百钱，走了。",
          "mode": "spoken"
        }
      ]
    }
  ]
}

