pi_result.artifact_text:
{
  "source_id": "TEXT",
  "cast": [
    {
      "id": "P01",
      "name": "格雷戈尔·萨姆沙"
    },
    {
      "id": "P02",
      "name": "母亲"
    },
    {
      "id": "P03",
      "name": "父亲"
    },
    {
      "id": "P04",
      "name": "妹妹"
    }
  ],
  "locations": [
    {
      "id": "L01",
      "name": "格雷戈尔的卧室"
    }
  ],
  "scenes": [
    {
      "sceneId": "L01",
      "characters": [
        "P01"
      ],
      "flow": [
        {
          "action": "格雷戈尔从不安的梦中醒来，仰面躺着，费力抬起沉重的头。"
        },
        {
          "action": "被子从他腹部的弧形硬片上滑落，露出许多细弱的腿在空中无助地颤动。"
        },
        {
          "speaker": "P01",
          "line": "我出什么事了？",
          "mode": "spoken",
          "delivery": "声音发哑"
        },
        {
          "action": "他环顾熟悉的四片墙壁，目光扫过桌上摊开的货品选样和墙上的金框画。"
        },
        {
          "speaker": "P01",
          "line": "这不是梦，房间还是我的房间。",
          "mode": "spoken"
        },
        {
          "action": "他望向窗户，雨点敲在铁皮窗檐上，屋里一片阴沉。"
        },
        {
          "speaker": "P01",
          "line": "要是再睡一会儿，把这些蠢事忘掉就好了。",
          "mode": "spoken",
          "delivery": "疲惫"
        },
        {
          "action": "他用力把身子翻向右侧，却又摇晃着弹回仰卧，试了一次又一次。"
        },
        {
          "speaker": "P01",
          "line": "翻不过去。老天，我干的是什么苦差事。",
          "mode": "spoken",
          "delivery": "喘着粗气"
        },
        {
          "action": "他闭上眼睛不再看那些乱动的腿，直到腰侧一阵钝痛才停下来。"
        }
      ]
    },
    {
      "sceneId": "L01",
      "characters": [
        "P01",
        "P02",
        "P03",
        "P04"
      ],
      "flow": [
        {
          "action": "格雷戈尔把背蹭到床柱边，好抬起头查看肚子上发痒的地方。"
        },
        {
          "speaker": "P01",
          "line": "这些白点是什么东西？",
          "mode": "spoken"
        },
        {
          "action": "他伸出一条细腿去摸，刚碰到就猛地缩回，全身一阵寒战。"
        },
        {
          "speaker": "P01",
          "line": "日复一日奔波，吃饭不定时。",
          "mode": "spoken",
          "delivery": "越说越恼"
        },
        {
          "speaker": "P01",
          "line": "别的推销员过得像老爷。",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "让这一切都见鬼去吧！",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "等我还清爸妈欠老板的钱，我就去辞职。",
          "mode": "spoken"
        },
        {
          "action": "他望向柜子上的闹钟，指针毫不迟疑地走过六点三刻。"
        },
        {
          "speaker": "P01",
          "line": "天哪，六点三刻了！火车七点开。",
          "mode": "spoken",
          "delivery": "急切"
        },
        {
          "speaker": "P01",
          "line": "样品没收拾好，五点那班车也错过了。",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "请假？我五年没生过病，他准会带着医生来。",
          "mode": "spoken"
        },
        {
          "action": "床头那边的门上响起小心翼翼的敲门声。"
        },
        {
          "speaker": "P02",
          "line": "格雷戈尔，六点三刻了，你不是还得赶火车吗？",
          "mode": "spoken",
          "delivery": "声音柔和"
        },
        {
          "action": "格雷戈尔一惊，张口回答，声音里夹着一股压不住的尖声。"
        },
        {
          "speaker": "P01",
          "line": "是的，是的，谢谢妈妈，我这就起床。",
          "mode": "spoken",
          "delivery": "尖细发颤"
        },
        {
          "action": "母亲踢踢踏踏走远，父亲随即用拳头敲响侧面那扇门。"
        },
        {
          "speaker": "P03",
          "line": "格雷戈尔！格雷戈尔！你怎么啦？",
          "mode": "spoken",
          "delivery": "低沉急促"
        },
        {
          "speaker": "P03",
          "line": "格雷戈尔！格雷戈尔！",
          "mode": "spoken",
          "delivery": "压低声音再催"
        },
        {
          "action": "另一侧的门传来妹妹轻轻的敲门声。"
        },
        {
          "speaker": "P04",
          "line": "格雷戈尔？你是不是不舒服？你需要什么吗？",
          "mode": "spoken",
          "delivery": "带着担心"
        },
        {
          "speaker": "P01",
          "line": "我这就好了。",
          "mode": "spoken",
          "delivery": "一字一顿，小心发音"
        },
        {
          "speaker": "P04",
          "line": "格雷戈尔，开开门，我求你了。",
          "mode": "spoken",
          "delivery": "轻声恳求"
        },
        {
          "action": "格雷戈尔一动不动地躺着，目光停在锁住的门上。"
        }
      ]
    }
  ]
}

{
  "source_id": "TEXT",
  "cast": [
    {
      "id": "P01",
      "name": "贾妃"
    },
    {
      "id": "P02",
      "name": "贾母"
    },
    {
      "id": "P03",
      "name": "王夫人"
    },
    {
      "id": "P04",
      "name": "贾政"
    },
    {
      "id": "P05",
      "name": "宝玉"
    },
    {
      "id": "P06",
      "name": "王熙凤"
    },
    {
      "id": "P07",
      "name": "邢夫人"
    },
    {
      "id": "P08",
      "name": "李纨"
    },
    {
      "id": "P09",
      "name": "迎春"
    },
    {
      "id": "P10",
      "name": "探春"
    },
    {
      "id": "P11",
      "name": "惜春"
    }
  ],
  "locations": [
    {
      "id": "L01",
      "name": "贾母正室"
    },
    {
      "id": "L02",
      "name": "大观园"
    }
  ],
  "scenes": [
    {
      "sceneId": "L01",
      "characters": [
        "P01",
        "P02",
        "P03",
        "P04",
        "P05",
        "P06",
        "P07",
        "P08",
        "P09",
        "P10",
        "P11"
      ],
      "flow": [
        {
          "action": "乐止，贾妃自座上起身。"
        },
        {
          "action": "贾母、王夫人跪止不迭。"
        },
        {
          "action": "贾妃一手搀贾母、一手搀王夫人，三人相对呜咽对泣。"
        },
        {
          "action": "邢夫人、李纨、王熙凤与迎、探、惜三姊妹在旁围绕，垂泪无言。"
        },
        {
          "action": "贾妃忍悲强笑。"
        },
        {
          "speaker": "P01",
          "line": "当日既送我到那不得见人的去处，好容易今日回家娘儿们一会，反倒哭起来。",
          "mode": "spoken",
          "delivery": "强笑"
        },
        {
          "speaker": "P01",
          "line": "一会子我就要走了，又不知多晚才来了！",
          "mode": "spoken",
          "delivery": "哽咽"
        },
        {
          "action": "王熙凤上来解劝，贾母、王夫人让贾妃归座。"
        },
        {
          "speaker": "P01",
          "line": "薛姨妈、宝钗、黛玉为何不见？",
          "mode": "spoken",
          "delivery": "问"
        },
        {
          "speaker": "P03",
          "line": "外眷无职，未敢擅入。",
          "mode": "spoken",
          "delivery": "起身启奏"
        },
        {
          "action": "贾妃听了，忙命快请。"
        },
        {
          "action": "贾政至帘外问安，贾妃垂帘还礼。"
        },
        {
          "speaker": "P04",
          "line": "田舍之家，虽齑盐布帛，终能聚天伦之乐。",
          "mode": "spoken",
          "delivery": "隔帘含泪"
        },
        {
          "speaker": "P04",
          "line": "今虽富贵已极，骨肉各方，然终无意趣！",
          "mode": "spoken",
          "delivery": "隔帘含泪"
        },
        {
          "speaker": "P04",
          "line": "臣只业业兢兢，恪守本职；请贵妃自加珍爱，莫念老拙。",
          "mode": "spoken",
          "delivery": "含泪"
        },
        {
          "speaker": "P01",
          "line": "只以国事为重，暇时保养，切勿记念。",
          "mode": "spoken",
          "delivery": "隔帘"
        },
        {
          "speaker": "P04",
          "line": "园中亭台轩馆，皆是宝玉题的；若有一二可看的，请赐名。",
          "mode": "spoken",
          "delivery": "启奏"
        },
        {
          "speaker": "P01",
          "line": "果进益了。",
          "mode": "spoken",
          "delivery": "含笑"
        },
        {
          "action": "贾政退出。"
        },
        {
          "speaker": "P01",
          "line": "宝玉为何不进见？",
          "mode": "spoken",
          "delivery": "问"
        },
        {
          "speaker": "P02",
          "line": "无谕，外男不敢擅入。",
          "mode": "spoken",
          "delivery": "启奏"
        },
        {
          "action": "贾妃命引进来，宝玉入内，先行国礼毕。"
        },
        {
          "action": "贾妃命宝玉进前，揽于怀内，抚其头颈。"
        },
        {
          "speaker": "P01",
          "line": "比先竟长了好些……",
          "mode": "spoken",
          "delivery": "笑"
        },
        {
          "action": "一语未终，贾妃泪如雨下。"
        },
        {
          "speaker": "P06",
          "line": "筵宴齐备，请贵妃游幸。",
          "mode": "spoken",
          "delivery": "启奏"
        }
      ]
    },
    {
      "sceneId": "L02",
      "characters": [
        "P01",
        "P02",
        "P03",
        "P05",
        "P06"
      ],
      "flow": [
        {
          "action": "贾妃与贾母、王夫人起身，命宝玉导引，同至园门前。"
